17	const AuthContext = createContext<AuthContextType | undefined>(undefined);
18	
19	export function AuthProvider({ children }: { children: ReactNode }) {
20	  const [user, setUser] = useState<User | null>(null);
21	  const [isAuthenticated, setIsAuthenticated] = useState(false);
22	  const [isAdmin, setIsAdmin] = useState(false);
23	
24	  useEffect(() => {
25	    // 检查本地存储中的 token
26	    const token = localStorage.getItem('access_token');
27	    const storedUser = localStorage.getItem('user');
28	
29	    if (token && storedUser) {
30	      try {
31	        const userData = JSON.parse(storedUser);
32	        setUser(userData);
33	        setIsAuthenticated(true);
34	        setIsAdmin(userData.role === 'ADMIN');
35	      } catch {
36	        // 清除无效的用户数据
37	        localStorage.removeItem('user');
38	        localStorage.removeItem('access_token');
39	      }
40	    }
41	  }, []);
42	
43	  const login = (username: string, accessToken: string, role: string = 'USER') => {
44	    const userData: User = { username, email: '', role };
45	    setUser(userData);
46	    setIsAuthenticated(true);
47	    setIsAdmin(role === 'ADMIN');
48	    localStorage.setItem('access_token', accessToken);
49	    localStorage.setItem('user', JSON.stringify(userData));
50	  };
51	
52	  const logout = () => {
53	    setUser(null);
54	    setIsAuthenticated(false);
55	    setIsAdmin(false);
56	    localStorage.removeItem('access_token');
57	    localStorage.removeItem('refresh_token');
58	    localStorage.removeItem('user');
59	  };
60	
61	  return (
62	    <AuthContext.Provider value={{ user, isAuthenticated, isAdmin, login, logout }}>
63	      {children}
64	    </AuthContext.Provider>
65	  );
66	}
